                  [id]="'person-statement-asof-' + p.id"
                  data-testid="person-statement-asof"
                  placeholder="YYYY-MM-DD"
                  [value]="statementDates()[p.id] ?? ''"
                  (input)="setStatementDate(p.id, value($event))"
